      "type": "string",
      "title": "Cache lifetime",
      "description": "auto follows Claude Code's rules and corrects itself from request timing; 5m or 1h pins it",
      "default": "auto",
      "options": [
        "auto",
        "5m",
        "1h"
      ]
    },
    "toast": {
